        if (type == "monthly") output = AddMonthlyTotals(output);
        if (email) new SmtpClient("smtp").Send(new MailMessage("r@x.com", to2, "Report", "") { Attachments = { new Attachment(new MemoryStream(output), "r." + format) } });
        return output;
    }
